/* Gang notes, tactics and alchemy, independently implemented from observed forms. */
(function(){
'use strict';
const R=()=>globalThis.RULES_DATA||{},num=value=>Number(value)||0;
const edition=value=>String(value||gang()?.edition||data.edition||'N23').toLowerCase();
const gtButton=(action,label,extra='',cls='')=>`<button type="button" class="btn small ${cls}" data-gt="${action}" ${extra}>${label}</button>`;
const gtCombo=(name,label,options,value='',placeholder='Select an option')=>MMWidgets.combo(name,label,options,value,placeholder);
const gtCheckbox=(name,label,value=false)=>`<label class="checkline"><input type="checkbox" name="${esc(name)}" ${value?'checked':''}><span>${esc(label)}</span></label>`;
const gtError=message=>{const node=document.querySelector('#gt-error');if(node)node.textContent=message;else alert(message);return false};
const members=g=>data.campaigns.flatMap(c=>(c.members||[]).filter(m=>m.gangId===g.id).map(member=>({campaign:c,member})));
const subtypes=f=>f.subtypes||f.fighter_subtypes||[f.subtype||f.type].filter(Boolean);
const effects=f=>Array.isArray(f.effects)?f.effects:Object.values(f.effects||{}).flat();
const injuries=f=>Array.isArray(f.injuries)?f.injuries:(f.effects?.injuries||[]);
const gtDie=()=>{const bytes=new Uint32Array(1);crypto.getRandomValues(bytes);return bytes[0]%6+1};
const gtNotice=message=>{let node=document.querySelector('#gt-notice');if(!node){node=document.createElement('div');node.id='gt-notice';node.className='gt-notice';node.setAttribute('role','status');document.body.append(node)}node.textContent=message;clearTimeout(node.gtTimer);node.gtTimer=setTimeout(()=>node.remove(),2800)};
function gtCredits(g){document.querySelector('.modal-head h2')?.insertAdjacentHTML('afterend',`<div class="modal-header-right gt-modal-credits"><span>Gang Credits</span><b class="credit-pill">${fmt(g.credits)}</b></div>`)}

// Notes use three independently saved fields, each with its own rich editor.
const gtNoteDrafts=new Map();let gtSelection=null;
const gtNoteFields=[{key:'notes',title:'Gang Notes',limit:1500,placeholder:"Add notes here, they'll appear on the Gang card when printed.",description:"They'll appear on the Gang card when printed."},{key:'backstory',title:'Gang Backstory',limit:2500,placeholder:'Add backstory here...'},{key:'privateNotes',title:'Private Notes',limit:2500,placeholder:'Add private notes here. Only you and your Arbitrators can view and edit these notes.',description:'Only you and your Arbitrators can view and edit these notes.'}];
function gtCleanHtml(value){
 const template=document.createElement('template');template.innerHTML=String(value||'');for(const font of template.content.querySelectorAll('font[color]')){const span=document.createElement('span');span.style.color=font.getAttribute('color');span.append(...font.childNodes);font.replaceWith(span)}
 const allowed=new Set(['P','BR','B','STRONG','I','EM','U','S','STRIKE','H1','H2','H3','UL','OL','LI','BLOCKQUOTE','A','SPAN','DIV']);
 const clean=node=>{for(const child of [...node.children]){if(['SCRIPT','STYLE','IFRAME','OBJECT','SVG','MATH','IMG'].includes(child.tagName)){child.remove();continue}clean(child);if(!allowed.has(child.tagName)){child.replaceWith(...child.childNodes);continue}for(const attribute of [...child.attributes]){if(attribute.name==='style'){const color=child.style.color,alignment=child.style.textAlign;child.removeAttribute('style');if(/^(#[\da-f]{3,8}|rgba?\([\d\s,.%]+\)|[a-z]+)$/i.test(color))child.style.color=color;if(['left','center','right','justify'].includes(alignment))child.style.textAlign=alignment}else if(!(child.tagName==='A'&&attribute.name==='href'&&/^(https?:|mailto:)/i.test(attribute.value)))child.removeAttribute(attribute.name)}if(child.tagName==='A'){child.setAttribute('target','_blank');child.setAttribute('rel','noopener noreferrer')}}};clean(template.content);return template.innerHTML;
}
const gtHtml=value=>/<[a-z][\s\S]*>/i.test(String(value||''))?gtCleanHtml(value):esc(value||'').replace(/\n/g,'<br>');
const gtPlain=value=>{const node=document.createElement('div');node.innerHTML=gtCleanHtml(value);return node.textContent||''};
function gtEditorToolbar(key,count,limit){const commands=[['bold','B','Bold'],['italic','I','Italic'],['underline','U','Underline'],['strikeThrough','S','Strikethrough'],['h1','H1','Heading 1'],['h2','H2','Heading 2'],['h3','H3','Heading 3'],['insertUnorderedList','☷','Bullet List'],['insertOrderedList','☷¹','Numbered List'],['blockquote','❞','Quote'],['justifyLeft','≡','Align Left'],['justifyCenter','≡','Align Center'],['justifyRight','≡','Align Right'],['justifyFull','☰','Justify']];return `<div class="gt-editor-toolbar" role="toolbar" aria-label="Text formatting">${commands.map(([command,label,title])=>gtButton('note-format',label,`data-command="${command}" data-key="${key}" title="${title}" aria-label="${title}"`,'gt-format')).join('')}${gtButton('note-colour','◉',`data-key="${key}" title="Text Colour" aria-label="Text Colour"`,'gt-format')}${gtButton('note-link','↗',`data-key="${key}" title="Add Link" aria-label="Add Link"`,'gt-format')}${gtButton('note-unlink','⊘',`data-key="${key}" title="Remove Link" aria-label="Remove Link"`,'gt-format')}<span class="gt-count ${count>limit?'gt-error':''}" data-gt-count="${key}">${count}/${limit}</span></div><div class="gt-colours" data-gt-colours="${key}" hidden>${[['Default','inherit'],['Black','#111111'],['White','#ffffff'],['Red','#dc2626'],['Orange','#ea580c'],['Yellow','#ca8a04'],['Green','#16a34a'],['Blue','#2563eb'],['Purple','#9333ea']].map(([title,color])=>gtButton('note-pick-colour',color==='inherit'?'A':'',`data-key="${key}" data-colour="${color}" title="${title}" style="background:${color==='inherit'?'transparent':color}"`,'gt-colour')).join('')}</div><div class="gt-link-form" data-gt-link="${key}" hidden><input type="url" data-gt-link-url="${key}" placeholder="https://example.com">${gtButton('note-insert-link','Add',`data-key="${key}"`)}</div>`}
function gtNoteCard(g,field){const slot=g.id+':'+field.key,editing=gtNoteDrafts.has(slot),content=editing?gtNoteDrafts.get(slot):gtHtml(g[field.key]||''),count=gtPlain(content).length;return `<section class="card gt-note-card" data-gt-note="${field.key}"><div class="section-heading"><h2>${field.title}</h2><div class="actions">${editing?gtButton('note-cancel','Cancel',`data-key="${field.key}"`)+gtButton('note-save','Save',`data-key="${field.key}" ${count>field.limit?'disabled':''}`,'primary'):gtButton('note-edit','Edit',`data-key="${field.key}"`)}</div></div>${editing?`<div class="gt-editor-wrap">${gtEditorToolbar(field.key,count,field.limit)}<div class="gt-editor" contenteditable="true" role="textbox" aria-multiline="true" aria-label="${field.title}" data-gt-editor="${field.key}" data-placeholder="${esc(field.placeholder)}">${content}</div></div>`:gtPlain(content).trim()?`<div class="gt-note-content">${content}</div>`:`<p class="gt-empty">No ${field.title.toLowerCase()} added.${field.description?' '+field.description:''}</p>`}${field.key==='privateNotes'&&g.privateNotesUpdatedAt&&!editing?`<p class="gt-note-updated">Updated: ${esc(new Date(g.privateNotesUpdatedAt).toLocaleString('en-CA',{dateStyle:'short',timeStyle:'short'}))}</p>`:''}</section>`}
gangNotesTab=function(g){return `<div class="gt-notes">${gtNoteFields.map(field=>gtNoteCard(g,field)).join('')}</div>`};
function gtNoteUpdate(editor,g){const key=editor.dataset.gtEditor,field=gtNoteFields.find(f=>f.key===key);if(!field)return;gtNoteDrafts.set(g.id+':'+key,editor.innerHTML);const count=editor.textContent.length,card=editor.closest('[data-gt-note]'),counter=card.querySelector('[data-gt-count]');counter.textContent=count+'/'+field.limit;counter.classList.toggle('gt-error',count>field.limit);card.querySelector('[data-gt="note-save"]').disabled=count>field.limit}
function gtNoteCommand(key,command,value){const editor=document.querySelector(`[data-gt-editor="${key}"]`);if(!editor)return;editor.focus();const selection=getSelection();if(gtSelection&&editor.contains(gtSelection.commonAncestorContainer)){selection.removeAllRanges();selection.addRange(gtSelection)}if(document.execCommand){if(command==='foreColor')document.execCommand('styleWithCSS',false,true);if(/^h[123]$/.test(command)||command==='blockquote'){const node=selection.anchorNode?.nodeType===1?selection.anchorNode:selection.anchorNode?.parentElement;document.execCommand('formatBlock',false,node?.closest(command)?'p':command)}else document.execCommand(command,false,value)}gtNoteUpdate(editor,gang())}

// The actual edition and gang pack catalog drives every tactics choice.
let gtTacticsDraft=null;
const gtTacticKey=card=>card.tactics_cards_id||card.cardId||card.catalogId||card.presetId||card.id;
function gtPacks(g){let gt=(R().gangTypes||[]).find(x=>x.id===g.gangTypeId)||(R().gangTypes||[]).find(x=>x.gang_type===g.faction&&x.edition===edition(g.edition));const ids=new Set([gt?.id,gt?.parent_gang_type_id].filter(Boolean));return (R().tacticsPacks||[]).filter(p=>p.edition===edition(g.edition)&&(!p.gang_type_id||ids.has(p.gang_type_id))).map(p=>({...p,is_core:!p.gang_type_id,cards:(p.cards||(R().tactics||[]).filter(c=>c.tactics_cards_pack_id===p.id)).slice().sort((a,b)=>(a.d66_min??999)-(b.d66_min??999)||a.name.localeCompare(b.name))})).sort((a,b)=>a.name.localeCompare(b.name))}
const gtRange=card=>card.d66_min==null?'—':card.d66_min===card.d66_max?String(card.d66_min):card.d66_min+'–'+card.d66_max;
function gtTacticsMarkup(){const state=gtTacticsDraft,packs=gtPacks(state.g),core=packs.find(p=>p.is_core),pack=packs.find(p=>p.id===state.packId)||core,cards=pack?.cards||[],d6=cards.length&&cards.every(c=>c.d66_max==null||c.d66_max<=6),owned=new Set((state.g.tactics||[]).map(gtTacticKey)),rollable=cards.some(c=>c.d66_min!=null&&!owned.has(c.id));state.activePack=pack;return `<div class="gt-pack-options">${packs.filter(p=>!p.is_core).map(p=>`<label class="checkline"><input type="checkbox" data-gt-tactics-pack="${p.id}" ${state.packId===p.id?'checked':''}><span>${esc(p.name)}</span></label>`).join('')}</div><div class="gt-roll-row">${gtButton('tactics-roll',d6?'Roll D6':'Roll D66',rollable?'':'disabled')}<span class="muted" data-gt-tactics-result>${esc(state.rollMessage||'')}</span></div><div class="gt-tactics-picker">${cards.map(card=>{const isOwned=owned.has(card.id);return `<label class="gt-tactics-choice ${isOwned?'gt-owned':''}" id="gt-tactics-${card.id}"><input type="checkbox" data-gt-tactics-card="${card.id}" ${isOwned||state.selected.has(card.id)?'checked':''} ${isOwned?'disabled':''}><span class="gt-dice-range">${gtRange(card)}</span><span>${esc(card.name)}</span>${isOwned?'<small>Already added</small>':''}</label>`}).join('')||'<p class="gt-empty">No tactics cards available.</p>'}</div><p id="gt-error" class="gt-error" role="alert"></p>`}
function gtRefreshTactics(){const body=document.querySelector('.modal-bg .modal-body');if(!body||!gtTacticsDraft)return;body.innerHTML='<p class="gt-modal-helper">Pick the tactics cards this gang holds.</p>'+gtTacticsMarkup();document.querySelector('#modal-submit').disabled=gtTacticsDraft.selected.size===0}
function gtSyncTacticsSelection(){const state=gtTacticsDraft;if(!state)return;const owned=new Set((state.g.tactics||[]).map(gtTacticKey));document.querySelectorAll('[data-gt-tactics-card]').forEach(input=>{input.checked=owned.has(input.dataset.gtTacticsCard)||state.selected.has(input.dataset.gtTacticsCard)});const button=document.querySelector('#modal-submit');if(button)button.disabled=state.selected.size===0;const result=document.querySelector('[data-gt-tactics-result]');if(result)result.textContent=state.rollMessage||''}
function gtScrollToTactic(cardId){const row=document.getElementById('gt-tactics-'+cardId),picker=row?.closest('.gt-tactics-picker');if(!row||!picker)return;const item=row.getBoundingClientRect(),viewport=picker.getBoundingClientRect();if(item.top<viewport.top)picker.scrollTop+=item.top-viewport.top;else if(item.bottom>viewport.bottom)picker.scrollTop+=item.bottom-viewport.bottom}
function gtOpenTactics(g,{single=false,onChoose,title='Add Gang Tactics',submit='Add'}={}){extras(g);gtTacticsDraft={g,single,onChoose,selected:new Set(),packId:'',rollMessage:''};showModal(title,'<p class="gt-modal-helper">Pick the tactics cards this gang holds.</p>'+gtTacticsMarkup(),submit,()=>{const state=gtTacticsDraft;if(!state?.selected.size)return false;const cards=(R().tactics||[]).filter(c=>state.selected.has(c.id));if(!cards.length)return false;if(state.onChoose){state.onChoose(cards[0]);return true}for(const card of cards)if(!g.tactics.some(t=>gtTacticKey(t)===card.id))g.tactics.push(gtOwnedTactic(card));log(g,cards.length===1?cards[0].name+' tactics card added.':cards.length+' tactics cards added.');save();gtNotice(cards.length===1?'Tactics card added':cards.length+' tactics cards added');return true});document.querySelector('#modal-submit').disabled=true;document.querySelector('.modal').classList.add('gt-tactics-modal')}
function gtChooseTactic(g,onChoose,title='Develop Tactics'){gtOpenTactics(g,{single:true,onChoose,title,submit:'Choose'})}
function gtOwnedTactic(card){return {id:id(),cardId:card.id,catalogId:card.id,presetId:card.id,tactics_cards_id:card.id,name:card.name,description:'',source:card.pack_name||(R().tacticsPacks||[]).find(p=>p.id===card.tactics_cards_pack_id)?.name||'',d66_min:card.d66_min,d66_max:card.d66_max}}
tacticsTab=function(g){extras(g);return `<section class="card gt-tactics-section"><div class="section-heading"><h2>Gang Tactics</h2>${gtButton('tactics-add','Add')}</div><div class="table-wrap"><table><thead><tr><th>Name</th><th>Desc.</th><th>Action</th></tr></thead><tbody>${g.tactics.slice().sort((a,b)=>(a.d66_min??999)-(b.d66_min??999)||a.name.localeCompare(b.name)).map(card=>`<tr><td>${esc(card.name)}</td><td>${card.description||card.effect?gtButton('tactics-view','▤',`data-card="${card.id}" aria-label="View tactics card description"`):''}</td><td class="gt-row-actions">${gtButton('tactics-edit','✎',`data-card="${card.id}" aria-label="Edit" title="Edit"`)}${gtButton('tactics-delete','⌫',`data-card="${card.id}" aria-label="Delete" title="Delete"`,'danger')}</td></tr>`).join('')||'<tr><td colspan="3" class="gt-empty">No gang tactics yet.</td></tr>'}</tbody></table></div></section>`};
const gtOldBattles=gangBattles;gangBattles=function(g){const html=gtOldBattles(g),start=html.indexOf('<section'),end=html.indexOf('</section>',start);return end<0?html:html.slice(0,start)+(edition(g.edition)==='n26'?tacticsTab(g):'')+html.slice(end+10)};
function gtEditTactic(g,card){formModal('Edit Tactics Card',`<p class="wide gt-modal-helper">Description for ${esc(card.name)}</p><label class="wide gt-description-label"><span>Description <small data-gt-tactics-count>${(card.description||card.effect||'').length}/1500 characters</small></span><textarea name="description" data-gt-tactics-description placeholder="Enter the card's rules text or your own notes...">${esc(card.description||card.effect||'')}</textarea></label>`,values=>{if(values.description.length>1500)return false;card.description=values.description.trim();card.effect=card.description;save();gtNotice('Description updated')},'Save');document.querySelector('#modal-form').dataset.gtTacticsEdit=card.id;document.querySelector('#modal-submit').disabled=true}

// Source-specific alchemy presets are unavailable until the supplied original is verified.
let gtChemDraft=null;
function gtCanChem(){return false;}
function gtChemCost(){return null;}
function gtChemCapture(){}
function gtChemValidate(){}
function gtChemRedraw(){}
function gtChem(){return window.MMOfficialSource?.showPending();}
const gtOldStash=stashTab;stashTab=function(g){let html=gtOldStash(g);if(gtCanChem(g))html=html.replace('<div class="actions">','<div class="actions">'+gtButton('chem-open','Chem-alchemy'));return html};

// Rule-driven post-cycle resolution awaits the supplied original.
function gtPostCyclePanel(){return '<section id="gt-pc-panel" class="gt-pc-panel"><h3 data-i18n-ko="사이클 기록">Cycle records</h3><p data-i18n-ko="공식 원본 확인 전에는 자동 사이클 판정을 제공하지 않습니다.">Automatic cycle resolution is unavailable until the official original is verified.</p></section>';}
function gtPostCycleAction(event,target){if(!target?.dataset.gt?.startsWith('pc-'))return false;window.MMOfficialSource?.showPending({activator:target});return true;}
function gtPostCycleChange(){return window.MMOfficialSource?.showPending();}

const gtOldGangCampaign=gangCampaignTab;
gangCampaignTab=function(g){let html=gtOldGangCampaign(g),owned=members(g).flatMap(({campaign:c})=>(c.territories||[]).filter(t=>t.gangId===g.id).map(t=>({...t,campaign:c})));html+=`<section class="card gt-territories"><div class="section-heading"><h2>Gang Territories</h2></div>${owned.length?`<div class="table-wrap"><table><thead><tr><th>Name</th><th>Campaign</th></tr></thead><tbody>${owned.map(t=>`<tr><td>${esc(t.name)}</td><td><button class="gt-text-button" data-open-campaign="${t.campaign.id}">${esc(t.campaign.name)}</button></td></tr>`).join('')}</tbody></table></div>`:'<p class="gt-empty">No territories controlled.</p>'}</section>`;if(typeof gtPostCyclePanel==='function')html+=gtPostCyclePanel(g);return html};

window.addEventListener('click',event=>{
 const legacy=event.target.closest('[data-ext="new-tactic"],[data-ext="delete-tactic"],[data-ext="edit-gang-story"],[data-ext="edit-gang-private"],[data-play="post-cycle"],[data-parity="post-cycle"]'),target=event.target.closest('[data-gt]');
 if(!target&&!legacy)return;event.stopImmediatePropagation();event.preventDefault();const g=gang();if(!g)return;
 const action=target?.dataset.gt||(legacy.dataset.ext==='new-tactic'?'tactics-add':legacy.dataset.ext==='delete-tactic'?'tactics-delete':legacy.dataset.ext==='edit-gang-story'?'note-legacy-story':legacy.dataset.ext==='edit-gang-private'?'note-legacy-private':'post-cycle');
 if(action.startsWith('pc-')){if(typeof gtPostCycleAction==='function')gtPostCycleAction(event,target,g);return}
 const key=target?.dataset.key,field=gtNoteFields.find(f=>f.key===key);
 if(action==='note-edit'||action.startsWith('note-legacy')){const noteKey=action==='note-legacy-story'?'backstory':action==='note-legacy-private'?'privateNotes':key;gtNoteDrafts.set(g.id+':'+noteKey,gtHtml(g[noteKey]||''));save()}
 else if(action==='note-cancel'){gtNoteDrafts.delete(g.id+':'+key);save()}
 else if(action==='note-save'){const editor=document.querySelector(`[data-gt-editor="${key}"]`);if(!editor||editor.textContent.length>field.limit)return;g[key]=editor.textContent.trim()?gtCleanHtml(editor.innerHTML):'';if(key==='privateNotes')g.privateNotesUpdatedAt=now();gtNoteDrafts.delete(g.id+':'+key);log(g,field.title+' updated.');save();gtNotice(field.title+' updated successfully')}
 else if(action==='note-format')gtNoteCommand(key,target.dataset.command);
 else if(action==='note-colour'){const picker=document.querySelector(`[data-gt-colours="${key}"]`);picker.hidden=!picker.hidden}
 else if(action==='note-pick-colour'){gtNoteCommand(key,'foreColor',target.dataset.colour);document.querySelector(`[data-gt-colours="${key}"]`).hidden=true}
 else if(action==='note-link'){const box=document.querySelector(`[data-gt-link="${key}"]`);box.hidden=!box.hidden;if(!box.hidden&&matchMedia('(pointer:fine)').matches)box.querySelector('input').focus({preventScroll:true})}
 else if(action==='note-unlink')gtNoteCommand(key,'unlink');
 else if(action==='note-insert-link'){const input=document.querySelector(`[data-gt-link-url="${key}"]`),url=input.value.trim();if(!/^(https?:\/\/|mailto:)/i.test(url)){input.setCustomValidity('Enter a valid https://, http:// or mailto: link.');input.reportValidity();return}input.setCustomValidity('');gtNoteCommand(key,'createLink',url);document.querySelector(`[data-gt-link="${key}"]`).hidden=true}
 else if(action==='tactics-add')gtOpenTactics(g);
 else if(action==='tactics-roll'){const state=gtTacticsDraft;if(!state)return;const pack=state.activePack,cards=pack?.cards||[],owned=new Set(g.tactics.map(gtTacticKey)),isD6=cards.every(c=>c.d66_max==null||c.d66_max<=6);let roll=0,card;for(let attempt=0;attempt<50;attempt++){roll=isD6?gtDie():gtDie()*10+gtDie();card=cards.find(c=>c.d66_min!=null&&roll>=c.d66_min&&roll<=c.d66_max);if(!card||!owned.has(card.id))break}state.rollMessage=card?roll+': '+card.name:'Roll '+roll+': no matching tactics card';if(card&&!owned.has(card.id)){state.selected=new Set([card.id]);log(g,'Tactics roll '+roll+': '+card.name);localStorage.setItem(KEY,JSON.stringify(data))}gtSyncTacticsSelection();if(card)gtScrollToTactic(card.id)}
 else if(action==='tactics-edit'){const card=g.tactics.find(c=>c.id===target.dataset.card);if(card)gtEditTactic(g,card)}
 else if(action==='tactics-view'){const card=g.tactics.find(c=>c.id===target.dataset.card);if(card)showModal(esc(card.name),`<p class="gt-tactics-description">${esc(card.description||card.effect||'')}</p>`,'Close',()=>true)}
 else if(action==='tactics-delete'){const card=g.tactics.find(c=>c.id===(target?.dataset.card||legacy?.dataset.id));if(card)showModal('Remove Tactics Card',`<p>Remove <strong>${esc(card.name)}</strong> from this gang's tactics?</p>`,'Remove',()=>{g.tactics=g.tactics.filter(c=>c.id!==card.id);log(g,card.name+' tactics card removed.');save();gtNotice(card.name+' removed')})}
 else if(action==='chem-open')gtChem(g);
 else if(action==='chem-discount')window.MMOfficialSource?.showPending({activator:target});
 else if(action==='post-cycle'){closeModal();data.tab='campaign-link';data.view='gang';save();document.querySelector('.gt-pc-panel')?.scrollIntoView?.({block:'start'})}
},true);
window.addEventListener('change',event=>{
 const target=event.target,g=gang();if(!g)return;if(target.closest('[data-gt-pc-action]')){if(typeof gtPostCycleChange==='function')gtPostCycleChange(event,g);return}
 if(target.matches('[data-gt-tactics-pack]')){gtTacticsDraft.packId=target.checked?target.dataset.gtTacticsPack:'';gtTacticsDraft.selected.clear();gtTacticsDraft.rollMessage='';gtRefreshTactics()}
 if(target.matches('[data-gt-tactics-card]')){const state=gtTacticsDraft;if(state.single)state.selected=new Set(target.checked?[target.dataset.gtTacticsCard]:[]);else if(target.checked)state.selected.add(target.dataset.gtTacticsCard);else state.selected.delete(target.dataset.gtTacticsCard);gtSyncTacticsSelection()}
 if(target.closest('#gt-chem-form')){window.MMOfficialSource?.showPending();return}
},true);
window.addEventListener('input',event=>{const target=event.target,g=gang();if(!g)return;if(target.matches('[data-gt-editor]'))gtNoteUpdate(target,g);if(target.matches('[data-gt-tactics-description]')){document.querySelector('[data-gt-tactics-count]').textContent=target.value.length+'/1500 characters';const card=g.tactics.find(c=>c.id===target.closest('form').dataset.gtTacticsEdit);document.querySelector('#modal-submit').disabled=target.value.length>1500||target.value.trim()===(card?.description||card?.effect||'').trim()}if(target.closest('#gt-chem-form')){gtChemCapture();gtChemValidate()}},true);
document.addEventListener('selectionchange',()=>{const selection=getSelection();if(selection?.rangeCount){const range=selection.getRangeAt(0),node=range.commonAncestorContainer.nodeType===1?range.commonAncestorContainer:range.commonAncestorContainer.parentElement;if(node?.closest('[data-gt-editor]'))gtSelection=range.cloneRange()}});
window.addEventListener('mousedown',event=>{if(event.target.closest('[data-gt="note-format"],[data-gt="note-pick-colour"],[data-gt="note-colour"],[data-gt="note-link"],[data-gt="note-unlink"]'))event.preventDefault()},true);
window.GangTools={notes:gangNotesTab,tactics:tacticsTab,addTactics:gtOpenTactics,chooseTactic:gtChooseTactic,chem:gtChem,packs:gtPacks,sanitize:gtCleanHtml};
render();
})();
